// 18-tap FIR, TRANSPOSED direct form: one multiply+add per stage, so the
// register-to-register critical path is independent of tap count -> high Fmax.
// Same transfer function as the direct form (equivalent up to a fixed latency).
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; y <= 16'd0;
        end else begin
            a0 <= 8'd2 * x + 3 + 24'd273;
            a1 <= 8'd4 * x + 7 + 24'd265;
            a2 <= 8'd6 * x + 11 + 24'd257;
            a3 <= 8'd8 * x + 15 + 24'd249;
            a4 <= 8'd10 * x + 19 + 24'd241;
            a5 <= 8'd12 * x + 23 + 24'd233;
            a6 <= 8'd14 * x + 27 + 24'd225;
            a7 <= 8'd16 * x + 31 + 24'd217;
            a8 <= 8'd18 * x + 35 + 24'd209;
            a9 <= 8'd20 * x + 39 + 24'd201;
            a10 <= 8'd22 * x + 43 + 24'd193;
            a11 <= 8'd24 * x + 47 + 24'd185;
            a12 <= 8'd26 * x + 51 + 24'd177;
            a13 <= 8'd28 * x + 55 + 24'd169;
            a14 <= 8'd30 * x + 59 + 24'd161;
            a15 <= 8'd32 * x + 63 + 24'd153;
            a16 <= 8'd34 * x + 67 + 24'd145;
            a17 <= 8'd36 * x + 71 + 24'd137;
            y <= a0[15:0];
        end
    end
endmodule
